export function getFrontmatterForRoute(pathname: string): FrontmatterData | null {
	const pathOnly = pathname.split('#')[0]?.split('?')[0] || '/';
	const normalized = pathOnly !== '/' && pathOnly.endsWith('/') ? pathOnly.slice(0, -1) : pathOnly;
	return frontmatterByPath[normalized] || null;
}
